-- Fresh-bootstrap BPM model seeds for tenant 1.
-- Scope: creates unpublished Flowable models and editor resources for the recommended manifest assets,
-- excluding zsjos_partner_open_request. Existing tenant/key models are preserved.
-- Dependencies: complete core/EAM/ZSJOS migrations, tenant 1, BPM forms, and at least one enabled tenant user.
-- Repeatability: model-key and fixed-resource guards prevent duplicates; no deployment or process instance is created.
-- Rollback limitation: remove only never-published seed models through the BPM service; do not delete ACT_* rows manually.

DROP PROCEDURE IF EXISTS `zsjos_seed_bpm_models`;
DELIMITER $$
CREATE PROCEDURE `zsjos_seed_bpm_models`()
BEGIN
  DECLARE bpm_seed_form_id bigint DEFAULT NULL;
  DECLARE bpm_seed_manager_ids json;
  DECLARE bpm_seed_meta json;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  IF NOT EXISTS (SELECT 1 FROM system_tenant WHERE id=1 AND status=0 AND deleted=b'0') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='BPM model seeds require enabled tenant 1';
  END IF;
  SELECT COALESCE(JSON_ARRAYAGG(enabled_user.id),JSON_ARRAY())
    INTO bpm_seed_manager_ids
  FROM (SELECT id FROM system_users
        WHERE tenant_id=1 AND status=0 AND deleted=b'0' ORDER BY id) enabled_user;
  IF JSON_LENGTH(bpm_seed_manager_ids)=0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='BPM model seeds require an enabled tenant-1 manager user';
  END IF;

  START TRANSACTION;
  INSERT INTO bpm_category
    (`name`,`code`,`description`,`status`,`sort`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`)
  SELECT '通用审批','general-module','初始化流程模型的默认分类',0,10,'bootstrap-bpm-models',NOW(),'bootstrap-bpm-models',NOW(),b'0',1
  WHERE NOT EXISTS (SELECT 1 FROM bpm_category WHERE tenant_id=1 AND code='general-module' AND deleted=b'0');

  -- eam_asset_transfer (1.0.0); asset SHA-256 a12d0e51087c1ac4b4d2a6e789947bbeccc02c73da2a962fb26c9a300ad8ed44
  SET bpm_seed_form_id=NULL;
  SET bpm_seed_meta=JSON_SET(
    CAST('{"icon":null,"description":"领用、借用和调拨的统一资产流转审批与履行流程","type":20,"formType":20,"formId":null,"formCustomCreatePath":"/eam/transfer","formCustomViewPath":"/eam/transfer/ApprovalDetail","visible":false,"startUserIds":[],"startDeptIds":[],"managerUserIds":[],"sort":100,"allowCancelRunningProcess":true,"allowWithdrawTask":false,"autoApprovalType":0,"processIdRule":{"enable":false,"prefix":"","infix":"","postfix":"","length":5},"titleSetting":{"enable":false,"title":""},"summarySetting":{"enable":false,"summary":[]},"printTemplateSetting":{"enable":false,"template":null}}' AS JSON),
    '$.managerUserIds',JSON_EXTRACT(bpm_seed_manager_ids,'$'),
    '$.formId',bpm_seed_form_id);
  INSERT INTO ACT_GE_BYTEARRAY (`ID_`,`REV_`,`NAME_`,`DEPLOYMENT_ID_`,`BYTES_`,`GENERATED_`)
  SELECT 'seed-src-53997d6ee5bc218b75f401f7',1,'source',NULL,UNHEX(''),0
  WHERE NOT EXISTS (SELECT 1 FROM ACT_RE_MODEL WHERE KEY_='eam_asset_transfer' AND TENANT_ID_='1')
    AND NOT EXISTS (SELECT 1 FROM ACT_GE_BYTEARRAY WHERE ID_='seed-src-53997d6ee5bc218b75f401f7');
  INSERT INTO ACT_GE_BYTEARRAY (`ID_`,`REV_`,`NAME_`,`DEPLOYMENT_ID_`,`BYTES_`,`GENERATED_`)
  SELECT 'seed-extra-53997d6ee5bc218b75f401f7',1,'source-extra',NULL,UNHEX(''),0
  WHERE NOT EXISTS (SELECT 1 FROM ACT_RE_MODEL WHERE KEY_='eam_asset_transfer' AND TENANT_ID_='1')
    AND NOT EXISTS (SELECT 1 FROM ACT_GE_BYTEARRAY WHERE ID_='seed-extra-53997d6ee5bc218b75f401f7');
  INSERT INTO ACT_RE_MODEL
    (`ID_`,`REV_`,`NAME_`,`KEY_`,`CATEGORY_`,`CREATE_TIME_`,`LAST_UPDATE_TIME_`,`VERSION_`,`META_INFO_`,
     `DEPLOYMENT_ID_`,`EDITOR_SOURCE_VALUE_ID_`,`EDITOR_SOURCE_EXTRA_VALUE_ID_`,`TENANT_ID_`)
  SELECT 'seed-model-53997d6ee5bc218b75f401f7',1,'资产流转审批','eam_asset_transfer','general-module',NOW(3),NOW(3),1,
         CAST(bpm_seed_meta AS CHAR),NULL,'seed-src-53997d6ee5bc218b75f401f7','seed-extra-53997d6ee5bc218b75f401f7','1'
