         CAST(bpm_seed_meta AS CHAR),NULL,'seed-src-1bfbcb8973cb4d0343fd03db',NULL,'1'
  WHERE NOT EXISTS (SELECT 1 FROM ACT_RE_MODEL WHERE KEY_='zsjos_partner_withdrawal' AND TENANT_ID_='1');

  -- zsjos_student_contact_extension (1.0.0); asset SHA-256 0f86f6fb459d56cab490b46e9ff983571089a88ecccf988c586908c95ad6d4ec
  SET bpm_seed_form_id=NULL;
  SELECT id INTO bpm_seed_form_id FROM bpm_form WHERE tenant_id=1 AND remark='zsjos-system-form:student-contact-extension' AND deleted=b'0' LIMIT 1;
  IF bpm_seed_form_id IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing BPM form for zsjos_student_contact_extension';
  END IF;
  SET bpm_seed_meta=JSON_SET(
    CAST('{"icon":null,"description":"学员联系延期审批 initialization model","type":10,"formType":10,"formId":null,"formCustomCreatePath":null,"formCustomViewPath":null,"visible":false,"startUserIds":[],"startDeptIds":[],"managerUserIds":[],"sort":110,"allowCancelRunningProcess":true,"allowWithdrawTask":false,"autoApprovalType":0,"processIdRule":{"enable":false,"prefix":"","infix":"","postfix":"","length":5},"titleSetting":{"enable":false,"title":""},"summarySetting":{"enable":false,"summary":[]},"printTemplateSetting":{"enable":false,"template":null}}' AS JSON),
    '$.managerUserIds',JSON_EXTRACT(bpm_seed_manager_ids,'$'),
    '$.formId',bpm_seed_form_id);
  INSERT INTO ACT_GE_BYTEARRAY (`ID_`,`REV_`,`NAME_`,`DEPLOYMENT_ID_`,`BYTES_`,`GENERATED_`)
  SELECT 'seed-src-fdfa3788b54ac868393b1a8a',1,'source',NULL,UNHEX(''),0
  WHERE NOT EXISTS (SELECT 1 FROM ACT_RE_MODEL WHERE KEY_='zsjos_student_contact_extension' AND TENANT_ID_='1')
    AND NOT EXISTS (SELECT 1 FROM ACT_GE_BYTEARRAY WHERE ID_='seed-src-fdfa3788b54ac868393b1a8a');
  INSERT INTO ACT_RE_MODEL
    (`ID_`,`REV_`,`NAME_`,`KEY_`,`CATEGORY_`,`CREATE_TIME_`,`LAST_UPDATE_TIME_`,`VERSION_`,`META_INFO_`,
     `DEPLOYMENT_ID_`,`EDITOR_SOURCE_VALUE_ID_`,`EDITOR_SOURCE_EXTRA_VALUE_ID_`,`TENANT_ID_`)
  SELECT 'seed-model-fdfa3788b54ac868393b1a8a',1,'学员联系延期审批','zsjos_student_contact_extension','general-module',NOW(3),NOW(3),1,
         CAST(bpm_seed_meta AS CHAR),NULL,'seed-src-fdfa3788b54ac868393b1a8a',NULL,'1'
  WHERE NOT EXISTS (SELECT 1 FROM ACT_RE_MODEL WHERE KEY_='zsjos_student_contact_extension' AND TENANT_ID_='1');

  COMMIT;
END$$
DELIMITER ;
CALL `zsjos_seed_bpm_models`();
DROP PROCEDURE IF EXISTS `zsjos_seed_bpm_models`;
